class Solution {
public:
    vector<int> countSubTrees(int n, vector<vector<int>>& edges, string labels) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        vector<int> ans(n);
        vector<vector<int>> cnt(n, vector<int>(26, 0));
        vector<int> par(n, -1);
        vector<int> order;
        order.reserve(n);

        vector<int> stk;
        stk.reserve(n);
        stk.push_back(0);
        while (!stk.empty()) {
            int u = stk.back();
            stk.pop_back();
            order.push_back(u);
            for (int v : adj[u]) {
                if (v != par[u]) {
                    par[v] = u;
                    stk.push_back(v);
                }
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            cnt[u][labels[u] - 'a'] = 1;
            for (int v : adj[u]) {
                if (v != par[u]) {
                    for (int c = 0; c < 26; c++) {
                        cnt[u][c] += cnt[v][c];
                    }
                }
            }
            ans[u] = cnt[u][labels[u] - 'a'];
        }

        return ans;
    }
};
